          if(h<1||h>12||mi>59||q.ans!==t)add(W+q.label+' -> '+q.ans);
          const vs=q.choices.map(c=>c.v);if(vs.length!==4)add(W+'4 choices');
          tally(m[1]);S_['m'+mi]=1;
