            if(a!==l*x||l<2||l>12||x<2||x>12||!q.html.startsWith(VIZ.rectSides(l,x,{w:l,h:x},{unit:m[3]}))||!q.html.includes(sq))add(W+m[0]+' -> '+q.ans);
