            const k=s.indexOf(d),dot=s.indexOf('.'),e=k<dot?dot-1-k:-(k-dot),v=fmt(BigInt(d)*T**BigInt(e+3),3);
            if(a!==v||!q.choices.some(c=>c.v===v))add(W+q.label+' -> '+a+' want '+v);
            const vs=q.choices.map(c=>D(c.v));
