            {const vb=svg.match(/viewBox="0 0 ([\d.]+) ([\d.]+)"/);if(!vb||rc.some(p=>p[0]<0||p[1]<0||p[0]+48>+vb[1]+.01||p[1]+48>+vb[2]+.01))add(W+'a tap target sticks out of the picture '+L)}
