      let tot=[0,0];
      C.forEach((c,i)=>{const a=area2x(c);const A=[Math.abs(a[0])/2,Math.abs(a[1])/2];if(a[1]!==0||A[0]!==AR[KIND[i]])bad(w+': piece '+i+' area '+JSON.stringify(a));tot=add(tot,A)});
      if(!eqx(tot,[16,0]))bad(w+': areas add up to '+JSON.stringify(tot));
