        {const s=JSON.parse(JSON.stringify(st)),c=s.pc[i],k2=(c[0]+1)%8,[x,y]=TG.about(KIND[i],c[0],c[1],c[2],c[3],k2,c[1]);s.pc[i]=[k2,c[1],x,y];near.push(['turned 45',s])}
