    if(PICT.test(h)||/>[^<\s]+</.test(h))p.push('burst '+k+': text or emoji in the pieces');
    if(!/var\(--ill-[a-z]+-2\)/.test(h)||!/var\(--ill-white\)/.test(h))p.push('burst '+k+': pieces not shaded (shade tone and a white glint)');
