      const g=rlNew('meadow-0',{mode:'pro',seed:2,trial:true});g.cd=0;Object.assign(g.P,{d:oi2*RL_SEG,x:TO.rw[oi2]+.35,v:RL_CRUISE*RL_VMAX});
