        const st=rlNew(id,{mode:'pro',seed:1,trial:true,up:{grip:lv}});st.cd=0;Object.assign(st.P,{d:i*RL_SEG+1,x:(q[0]+q[1])/2,v:RL_CRUISE*RL_VMAX,vx:.8});
