    const m3=bbGlMesh(w3,1,1),kinds=new Set();for(let n=7;n<m3.t.v.length;n+=8)kinds.add(m3.t.v[n]);
    if(!m3.t.i.length||!kinds.has(1))bad('water and glass are not see-through with moving water: '+[...kinds]);
