  s=stS();if(palKey(s.pal)!=='Ocean'||!Array.isArray(s.gal)||Array.isArray(s.done)||s.items['m:17'].f[3]!=='s:#22c55e'||s.order[0]!=='m:17')bad('a v155 studio save: '+JSON.stringify(s));
