      if(!(s4.gates&1)||!s4.ev.some(e=>e[0]=='key'))bad('touching the key should open the door');
      Object.assign(s4.p,{x:g.x0-1.4,y:g.y0,gr:true,vy:0});for(let i=0;i<40;i++)hopStep(s4,{dir:1});
