    {const st=LS.make('tenf2',{seed:1,day:100});S.grade=5;LS.beat(st,LSB.indexOf('tog'));const t=LS.cur(st).lines.join(' ');S.grade=g0;if(t!==LS_TONE.teen.tog)bad.push('the lesson does not speak in the teen tone: '+t)}
