    if(!f||lsLast(f.build(null))!=='72')bad.push('steps of 24 × 3: '+(f&&f.build(null)));
    const fd=lsFixF(k2FixDiv,{kind:'num',label:'75 ÷ 4 = ?'});if(!fd||lsLast(fd.build(null))!=='18 R3')bad.push('steps of 75 ÷ 4: '+(fd&&fd.build(null)));
