    const st2=LS.make('tenf2',{seed:5,day:STRK.idx(today()),proof:true});st2.caught=true;LS.beat(st2,LSB.indexOf('show'));for(let k=0;k<2;k++){LS.answer(st2,LS.cur(st2).q.ans);LS.next(st2)}
